def build_loop(S, weak_actions, strong_actions, en_states,
               edges_by_action, internal_edge, succ, pred):
    required = []
    for a in strong_actions:
        es = en_states[a]
        if any(s in es for s in S):
            e = internal_edge(S, a)
            if e is not None:
                required.append(e)
    witnesses = []
    for a in weak_actions:
        es = en_states[a]
        if S <= es:
            e = internal_edge(S, a)
            if e is not None:
                required.append(e)
        else:
            w = None
            for s in S:
                if s not in es:
                    w = s
                    break
            if w is not None:
                witnesses.append(w)

    # choose root
    targets = set(witnesses)
    for (u, v, eid) in required:
        targets.add(u); targets.add(v)
    if targets:
        root = next(iter(targets))
    else:
        root = next(iter(S))

    # forward adjacency within graph (target, eid)
    fadj = [[] for _ in range(len(succ))]
    radj = [[] for _ in range(len(pred))]
    for s in range(len(succ)):
        for (tgt, eid, name) in succ[s]:
            fadj[s].append((tgt, eid))
            radj[tgt].append((s, eid))

    fpe, fpn = _bfs_paths(root, S, fadj, True)
    rpe, rpn = _bfs_paths(root, S, radj, False)

    def path_fwd(target):
        # root -> target edges
        if target == root:
            return []
        out = []
        cur = target
        while cur != root:
            eid = fpe[cur]
            out.append(eid)
            cur = fpn[cur]
        out.reverse()
        return out

    def path_back(target):
        # target -> root edges
        if target == root:
            return []
        out = []
        cur = target
        while cur != root:
            eid = rpe[cur]
            out.append(eid)
            cur = rpn[cur]
        return out

    walk = []
    for (u, v, eid) in required:
        walk.extend(path_fwd(u))
        walk.append(eid)
        walk.extend(path_back(v))
    for w in witnesses:
        walk.extend(path_fwd(w))
        walk.extend(path_back(w))

    if not walk:
        walk = [-1]
    return root, walk
